from typing import List, Tuple

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Create a grid to store values
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the provided values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize the dp table
    dp = [[[0, 0] for _ in range(N)] for _ in range(N)]

    # Fill the dp table
    for i in range(N):
        for j in range(N):
            for k in range(2):
                if i == 0 and j == 0:
                    dp[i][j][k] = grid[i][j]
                else:
                    val = grid[i][j]
                    if k == 0:
                        # Can only move right
                        dp[i][j][k] = dp[i][j-1][k] + val if j > 0 else dp[i][j][k]
                    else:
                        # Can only move down
                        dp[i][j][k] = dp[i-1][j][k] + val if i > 0 else dp[i][j][k]
                if i > 0 and j > 0:
                    # Can move diagonally to maximize the sum
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j-1][k] + val)

    # The result is the maximum sum collected by choosing either path first
    return max(dp[N-1][N-1]) if N >= 1 else 0
