def count_partitions(n: int, k: int, x: int) -> int:
    # Helper function to use recursion to find partitions
    def partitions(n, k, min_val):
        if n < 0:
            return 0
        if n == 0 and k == 0:
            return 1
        if k == 0:
            return 0
        count = 0
        for i in range(min_val, n // k + 1):
            count += partitions(n - i, k - 1, i)
        return count

    # Return the number of partitions of n into k parts, each at least x
    return partitions(n, k, x)
