def count_sequences(n: int, last: int, memo: dict) -> int:
    if (n, last) in memo:
        return memo[(n, last)]

    if n > last // 2:
        return 0

    if n == last:
        return 1

    count = 0
    for i in range(n + 1, last // 2 + 1):
        count += count_sequences(n, i, memo)

    memo[(n, last)] = count
    return count
